   level:"中",
   cat:"必考題",
   type:"num",
   stem:String.raw`\(\triangle ABC\) 中，\(A(-2,1)\)、\(B(4,3)\)、\(C(2,-3)\)。若 \(M\) 為 \(\overline{AB}\) 的中點，則直線 \(CM\) 的斜率為＿＿＿＿。`,
