   level:"易",
   cat:"陷阱題",
   type:"tf",
   stem:String.raw`小明計算 \(A(1,5)\)、\(B(4,-1)\) 連線的斜率，寫成 \(m_{AB}=\dfrac{-1-5}{1-4}=\dfrac{-6}{-3}=2\)。小明的計算正確。`,
